import ast
import json
from collections import Counter
def task_func(file_pointer):
    data = json.load(file_pointer)
    counter = Counter()

    for entry in data:
        if isinstance(entry, str):
            obj = ast.literal_eval(entry)
        else:
            obj = entry

        if isinstance(obj, dict):
            counter.update(obj.keys())

    return counter
